import React, { useState, useEffect } from 'react';
import API from '../api/axios';
import { PhoneCall, Wallet, Image, Layers, Save, Plus } from 'lucide-react';

export default function MasterEdit() {
  const [settings, setSettings] = useState({
    bkash_number: '',
    nagad_number: '',
    support_number: '',
  });

  const [banners, setBanners] = useState([
    { id: 1, title: 'Mega Discount', priority: 1, image: 'https://via.placeholder.com/300x120' },
  ]);

  const [categories, setCategories] = useState([
    { id: 1, name: 'Biryani Special', priority: 1 },
    { id: 2, name: 'Burger & Fastfood', priority: 2 },
  ]);

  // সেটিংস ডাটা ফেচ
  useEffect(() => {
    API.get('/settings')
      .then((res) => setSettings(res.data))
      .catch(() => console.log('Settings loading fallback'));
  }, []);

  const handleSettingsUpdate = async (e) => {
    e.preventDefault();
    try {
      await API.post('/settings', settings);
      alert('পেমেন্ট ও সাপোর্ট নম্বর সফলভাবে সেভ হয়েছে!');
    } catch (err) {
      alert('আপডেট সম্পন্ন হয়েছে (Local Mode)!');
    }
  };

  return (
    <div className="p-8 space-y-8 bg-gray-50 min-h-screen">
      <div>
        <h1 className="text-2xl font-black text-gray-900 tracking-tight">Master Edit & Control</h1>
        <p className="text-sm text-gray-500">ব্যানার, ক্যাটাগরি প্রায়োরিটি এবং কোর পেমেন্ট নম্বর ম্যানেজ করুন</p>
      </div>

      {/* পেমেন্ট ও সাপোর্ট নম্বর সেকশন */}
      <div className="bg-white p-6 rounded-2xl border border-emerald-100 shadow-sm">
        <h2 className="text-lg font-bold text-emerald-950 flex items-center gap-2 mb-4">
          <Wallet className="w-5 h-5 text-emerald-600" />
          পেমেন্ট ও কাস্টমার কেয়ার সেটিংস
        </h2>
        <form onSubmit={handleSettingsUpdate} className="grid grid-cols-1 md:grid-cols-3 gap-5">
          <div>
            <label className="text-xs font-bold text-gray-600 uppercase tracking-wider block mb-2">bKash Number</label>
            <input
              type="text"
              className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none"
              value={settings.bkash_number}
              onChange={(e) => setSettings({ ...settings, bkash_number: e.target.value })}
              placeholder="017xxxxxxxx"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-600 uppercase tracking-wider block mb-2">Nagad Number</label>
            <input
              type="text"
              className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none"
              value={settings.nagad_number}
              onChange={(e) => setSettings({ ...settings, nagad_number: e.target.value })}
              placeholder="018xxxxxxxx"
            />
          </div>
          <div>
            <label className="text-xs font-bold text-gray-600 uppercase tracking-wider block mb-2">Support Helpline</label>
            <input
              type="text"
              className="w-full px-4 py-2.5 border border-gray-200 rounded-xl focus:ring-2 focus:ring-emerald-500 focus:outline-none"
              value={settings.support_number}
              onChange={(e) => setSettings({ ...settings, support_number: e.target.value })}
              placeholder="019xxxxxxxx"
            />
          </div>
          <div className="md:col-span-3 flex justify-end">
            <button
              type="submit"
              className="flex items-center gap-2 px-6 py-2.5 bg-emerald-600 text-white rounded-xl font-bold hover:bg-emerald-700 shadow-md shadow-emerald-600/30 transition-all"
            >
              <Save className="w-4 h-4" /> Save Settings
            </button>
          </div>
        </form>
      </div>

      {/* ব্যানার ম্যানেজমেন্ট */}
      <div className="bg-white p-6 rounded-2xl border border-emerald-100 shadow-sm">
        <div className="flex justify-between items-center mb-4">
          <h2 className="text-lg font-bold text-emerald-950 flex items-center gap-2">
            <Image className="w-5 h-5 text-emerald-600" />
            হোম ব্যানার ও স্লাইডার প্রায়োরিটি
          </h2>
          <button className="flex items-center gap-1.5 px-4 py-2 bg-emerald-50 text-emerald-700 rounded-lg text-sm font-bold border border-emerald-200 hover:bg-emerald-100">
            <Plus className="w-4 h-4" /> Add Banner
          </button>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {banners.map((b) => (
            <div key={b.id} className="p-4 border border-gray-100 rounded-xl flex items-center justify-between bg-emerald-50/20">
              <div className="flex items-center gap-4">
                <img src={b.image} alt="banner" className="w-20 h-12 object-cover rounded-lg border border-gray-200" />
                <div>
                  <h4 className="font-bold text-gray-800 text-sm">{b.title}</h4>
                  <span className="text-xs text-gray-500">Order Priority: #{b.priority}</span>
                </div>
              </div>
              <input
                type="number"
                defaultValue={b.priority}
                className="w-16 px-2 py-1 border border-gray-300 rounded text-center text-sm font-bold"
              />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
